import os

# Let's check what database files are available in the current directory
print("Current directory:", os.getcwd())
print("\nFiles in current directory:")
for file in os.listdir('.'):
    if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
        print(f"  - {file}")

# Let's also check for the specific database mentioned in the error
db_path = '/path/to/your/database.db'
print(f"\nDoes '{db_path}' exist? {os.path.exists(db_path)}")

# If the database doesn't exist at the specified path, let's try to find it
if not os.path.exists(db_path):
    print("\nSearching for database files in current and parent directories...")
    for root, dirs, files in os.walk('.'):
        for file in files:
            if file.endswith('.db') or file.endswith('.sqlite') or file.endswith('.sqlite3'):
                print(f"Found: {os.path.join(root, file)}")
